module global_warming_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire edge_valid,\n    input wire [7:0] p,\n    input wire [7:0] q,\n    input wire [19:0] cost,\n    input wire edge_done,\n    output reg [23:0] result,\n    output reg impossible,\n    output reg done\n);\n\n    // State encoding\n    localparam [1:0] IDLE        = 2'b00;\n    localparam [1:0] COLLECT     = 2'b01;\n    localparam [1:0] COMPUTE     = 2'b10;\n    localparam [1:0] DONE_STATE  = 2'b11;\n    \n    // Internal registers\n    reg [1:0] state, next_state;\n    reg [19:0] cost_matrix [0:7][0:7];\n    reg [7:0] visited_nodes;\n    reg [7:0] components [0:7];\n    reg [3:0] comp_count;\n    reg [23:0] dp_table [0:255];\n    reg [23:0] total_cost;\n    \n    // BFS registers\n    reg [7:0] global_visited;\n    reg [7:0] current_comp;\n    reg [2:0] bfs_queue[0:7];\n    reg [2:0] queue_head;\n    reg [2:0] queue_tail;\n    reg [2:0] current_node;\n    \n    // DP registers\n    reg [7:0] comp_nodes\n    reg [3:0] comp_size;\n    reg [2:0] node_index [0:7];\n    reg [7:0] comp_mask;\n    reg [3:0] comp_idx;\n    reg [7:0] dp_mask;\n    reg [2:0] min_i, min_j;\n    \n    // Cycle counters\n    reg [9:0] cycle_counter;\n    \n    // Internal control flags\n    reg processing_comp;\n    reg comp_check_done;\n    reg comp_size_odd;\n    reg dp_processing;\n    reg dp_done;\n    reg dp_init;\n    \n    // Temporary variables\n    integer i, j, k;\n    \n    // FSM control logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            result <= 24'd0;\n            visited_nodes <= 8'd0;\n            comp_count <= 4'd0;\n            total_cost <= 24'd0;\n            \n            // Initialize cost matrix\n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    cost_matrix[i][j] <= 20'd0;\n                end\n            end\n            \n            // Initialize components\n            for (k = 0; k < 8; k = k + 1) begin\n                components[k] <= 8'd0;\n            end\n            \n            // Initialize DP table\n            for (k = 0; k < 256; k = k + 1) begin\n                dp_table[k] <= 24'hFFFFFF;\n            end\n            \n            cycle_counter <= 10'd0;\n            processing_comp <= 1'b0;\n            comp_check_done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    cycle_counter <= 10'd0;\n                    \n                    if (start) begin\n                        state <= COLLECT;\n                        visited_nodes <= 8'd0;\n                        comp_count <= 4'd0;\n                        // Clear cost matrix\n                        for (i = 0; i < 8; i = i + 1) begin\n                            for (j = 0; j < 8; j = j + 1) begin\n                                cost_matrix[i][j] <= 20'd0;\n                            end\n                        end\n                    end\n                end\n                \n                COLLECT: begin\n                    if (edge_valid) begin\n                        // Store edge in cost matrix (0-based index)\n                        cost_matrix[p-8'd1][q-8'd1] <= cost;\n                        cost_matrix[q-8'd1][p-8'd1] <= cost;\n                        visited_nodes <= visited_nodes | (8'd1 << (p-8'd1)) | (8'd1 << (q-8'd1));\n                    end\n                    \n                    if (edge_done) begin\n                        state <= COMPUTE;\n                        global_visited <= 8'd0;\n                        comp_count <= 4'd0;\n                        comp_idx <= 4'd0;\n                        queue_head <= 3'd0;\n                        queue_tail <= 3'd0;\n                        processing_comp <= 1'b1;\n                        cycle_counter <= 10'd0;\n                    end\n                end\n                \n                COMPUTE: begin\n                    cycle_counter <= cycle_counter + 10'd1;\n                    \n                    // Component detection (BFS)\n                    if (processing_comp && cycle_counter < 10'd100) begin\n                        if (global_visited != visited_nodes) begin\n                            // Find first unvisited node\n                            if (queue_tail == queue_head) begin\n                                for (k = 0; k < 8; k = k + 1) begin\n                                    if (!global_visited[k] && visited_nodes[k]) begin\n                                        current_node <= k;\n                                        global_visited[k] <= 1'b1;\n                                        current_comp <= 8'd1 << k;\n                                        bfs_queue[queue_tail] <= k;\n                                        queue_tail <= queue_tail + 3'd1;\n                                    end\n                                end\n                            end else begin\n                                // Process BFS queue\n                                current_node <= bfs_queue[queue_head];\n                                queue_head <= queue_head + 3'd1;\n                                \n                                for (k = 0; k < 8; k = k + 1) begin\n                                    if (cost_matrix[current_node][k] != 20'd0 && !global_visited[k]) begin\n                                        global_visited[k] <= 1'b1;\n                                        current_comp <= current_comp | (8'd1 << k);\n                                        bfs_queue[queue_tail] <= k;\n                                        queue_tail <= queue_tail + 3'd1;\n                                    end\n                                end\n                                \n                                if (queue_tail == queue_head) begin\n                                    components[comp_count] <= current_comp;\n                                    comp_count <= comp_count + 4'd1;\n                                    queue_head <= 3'd0;\n                                    queue_tail <= 3'd0;\n                                end\n                            end\n                        end else begin\n                            processing_comp <= 1'b0;\n                            comp_idx <= 4'd0;\n                            total_cost <= 24'd0;\n                            comp_check_done <= 1'b0;\n                            dp_init <= 1'b1;\n                        end\n                    end else if (!comp_check_done) begin\n                        // Check component sizes\n                        if (comp_idx < comp_count) begin\n                            comp_mask = components[comp_idx];\n                            comp_size = 4'd0;\n                            \n                            for (k = 0; k < 8; k = k + 1) begin\n                                if (comp_mask[k]) begin\n                                    comp_size = comp_size + 4'd1;\n                                    node_index[comp_size-4'd1] <= k;\n                                end\n                            end\n                            \n                            if (comp_size[0]) begin\n                                impossible <= 1'b1;\n                                state <= DONE_STATE;\n                            end\n                            \n                            comp_idx <= comp_idx + 4'd1;\n                        end else begin\n                            comp_check_done <= 1'b1;\n                            comp_idx <= 4'd0;\n                            dp_init <= 1'b1;\n                            dp_processing <= 1'b0;\n                        end\n                    end else if (!dp_done) begin\n                        // DP initialization\n                        if (dp_init) begin\n                            comp_mask = components[comp_idx];\n                            comp_size = 4'd0;\n                            \n                            // Extract nodes for component\n                            for (k = 0; k < 8; k = k + 1) begin\n                                if (comp_mask[k]) begin\n                                    node_index[comp_size] <= k;\n                                    comp_size = comp_size + 4'd1;\n                                end\n                            end\n                            \n                            // Initialize DP table\n                            dp_mask <= 8'd0;\n                            dp_table[0] <= 24'd0;\n                            for (k = 1; k < (1 << comp_size); k = k + 1) begin\n                                dp_table[k] <= 24'hFFFFFF;\n                            end\n                            dp_init <= 1'b0;\n                            dp_processing <= 1'b1;\n                        end\n                        \n                        // DP processing\n                        if (dp_processing && dp_mask < (1 << comp_size)) begin\n                            // Find first unmatched node\n                            min_i = 3'd7;\n                            for (k = 0; k < comp_size; k = k + 1) begin\n                                if (!dp_mask[k]) begin\n                                    min_i = k;\n                                end\n                            end\n                            \n                            // Pair with other unmatched nodes\n                            if (min_i < 3'd7) begin\n                                for (j = min_i + 3'd1; j < comp_size; j = j + 3'd1) begin\n                                    if (!dp_mask[j]) begin\n                                        if (dp_table[dp_mask] + cost_matrix[node_index[min_i]][node_index[j]] < dp_table[dp_mask | (8'd1 << min_i) | (8'd1 << j)]) begin\n                                            dp_table[dp_mask | (8'd1 << min_i) | (8'd1 << j)] <= dp_table[dp_mask] + cost_matrix[node_index[min_i]][node_index[j]];\n                                        end\n                                    end\n                                end\n                            end\n                            dp_mask <= dp_mask + 8'd1;\n                        end else if (dp_mask >= (1 << comp_size)) begin\n                            total_cost <= total_cost + dp_table[(1 << comp_size) - 1];\n                            comp_idx <= comp_idx + 4'd1;\n                            dp_init <= 1'b1;\n                            if (comp_idx == comp_count - 4'd1) begin\n                                dp_done <= 1'b1;\n                                state <= DONE_STATE;\n                            end\n                        end\n                    end\n                    // Timeout safeguard\n                    if (cycle_counter > 10'd1000) begin\n                        impossible <= 1'b1;\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule